using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using UnityEngine;
public static class EyeBoundaryBinding348{
 public static string Hash(Mesh mesh){using var stream=new MemoryStream();using(var w=new BinaryWriter(stream,System.Text.Encoding.UTF8,true)){w.Write(mesh.vertexCount);foreach(var p in mesh.vertices){w.Write(p.x);w.Write(p.y);w.Write(p.z);}foreach(var p in mesh.uv){w.Write(p.x);w.Write(p.y);}for(int s=0;s<mesh.subMeshCount;s++)foreach(int i in mesh.GetIndices(s))w.Write(i);foreach(var m in mesh.bindposes)for(int i=0;i<16;i++)w.Write(m[i]);}using var sha=SHA256.Create();return BitConverter.ToString(sha.ComputeHash(stream.ToArray())).Replace("-","").ToLowerInvariant();}
 public static int[][] ClosedRings(Mesh mesh,int skinSubmesh){var counts=new Dictionary<ulong,int>();var ix=mesh.GetIndices(skinSubmesh);for(int t=0;t<ix.Length;t+=3)for(int k=0;k<3;k++){int a=ix[t+k],b=ix[t+(k+1)%3];ulong key=((ulong)(uint)Math.Min(a,b)<<32)|(uint)Math.Max(a,b);counts[key]=counts.TryGetValue(key,out int n)?n+1:1;}var edges=new Dictionary<int,List<int>>();foreach(var q in counts.Where(x=>x.Value==1)){int a=(int)(q.Key>>32),b=(int)(q.Key&0xffffffff);if(!edges.ContainsKey(a))edges[a]=new List<int>();if(!edges.ContainsKey(b))edges[b]=new List<int>();edges[a].Add(b);edges[b].Add(a);}var unseen=new HashSet<int>(edges.Keys);var rings=new List<int[]>();while(unseen.Count>0){var pending=new Stack<int>();var component=new List<int>();int start=unseen.First();unseen.Remove(start);pending.Push(start);while(pending.Count>0){int p=pending.Pop();component.Add(p);foreach(int n in edges[p])if(unseen.Remove(n))pending.Push(n);}if(component.Count<3||component.Any(p=>edges[p].Count!=2))continue;var ordered=new List<int>();int at=start,previous=-1;do{ordered.Add(at);int next=edges[at][0]==previous?edges[at][1]:edges[at][0];previous=at;at=next;}while(at!=start&&ordered.Count<=component.Count);if(at==start&&ordered.Count==component.Count)rings.Add(ordered.ToArray());}return rings.ToArray();}
}
